// Только чтение: время — подменой часов браузера (_helpers/clock.ts); границы — с /zmanim того же дня и города (פתח תקווה).
// Уборка: /home на реальном времени в новом контексте.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { openHomeAt, tefillinRows, restoreTodayReminders, TEFILLIN_TEXT } from '../_helpers/reminders';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  timezoneId: 'Asia/Jerusalem',
});

const DAY = '2026-10-04'; // כ״ג תשרי — אסרו חג в Израиле (день из «מה קיים»)
const OFF = '+03:00';

/** «HH:MM» дня DAY ± dmin → момент ISO с явным смещением Израиля. */
function at(hhmm: string, dmin = 0): string {
  const [h, m] = hhmm.split(':').map(Number);
  const d = new Date(`${DAY}T${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:00${OFF}`);
  return new Date(d.getTime() + dmin * 60_000).toISOString();
}

/** /zmanim (часы уже подменены на полдень DAY): עלות השחר по 16.1° и שקיעת החמה. */
async function readZmanim(page: Page): Promise<{ alot161: string; shkiya: string }> {
  await page.goto('/zmanim');
  await expect(page.getByText('שקיעת החמה').first()).toBeVisible({ timeout: 25_000 });
  await expect(page.getByText('4 באוקטובר').first()).toBeVisible();
  let out = { alot161: '', shkiya: '' };
  await expect
    .poll(async () => {
      const L = (await page.locator('body').innerText()).split('\n').map((x) => x.replace(/[‎‏]/g, '').trim()).filter(Boolean);
      out = { alot161: '', shkiya: '' };
      for (let i = 0; i < L.length; i++) {
        if (L[i] !== 'עלות השחר' && L[i] !== 'שקיעת החמה') continue;
        let meth = '';
        let j = i + 1;
        while (j < L.length && j <= i + 3 && !/^\d{1,2}:\d{2}$/.test(L[j])) meth += L[j++];
        if (!/^\d{1,2}:\d{2}$/.test(L[j] ?? '')) continue;
        if (L[i] === 'עלות השחר' && meth.includes('16.1')) out.alot161 = L[j];
        if (L[i] === 'שקיעת החמה' && !out.shkiya) out.shkiya = L[j];
      }
      return Boolean(out.alot161 && out.shkiya);
    }, { timeout: 15_000 })
    .toBe(true);
  return out;
}

test.describe('Напоминания', () => {
  test('RM-06 «הנחת תפילין» видна от עלות השחר (16.1°) до שקיעה, после שקיעה и ночью — нет (Израиль, 4.10.2026) #3cc72778 @prod-safe @mobile', async ({ page, browser }, testInfo) => {
    try {
      // 1. Время 12:00 → /zmanim: границы дня.
      await openHomeAt(page, `${DAY}T12:00:00${OFF}`, { expectDay: DAY });
      const z = await readZmanim(page);

      const checks: { label: string; iso: string; tefillin: boolean }[] = [
        { label: '04:00 (ночь, до עלות השחר)', iso: `${DAY}T04:00:00${OFF}`, tefillin: false },
        { label: `עלות השחר 16.1° (${z.alot161}) − 1 мин`, iso: at(z.alot161, -1), tefillin: false },
        { label: `עלות השחר 16.1° (${z.alot161}) + 1 мин`, iso: at(z.alot161, +1), tefillin: true },
        { label: `שקיעה (${z.shkiya}) − 1 мин`, iso: at(z.shkiya, -1), tefillin: true },
        { label: `שקיעה (${z.shkiya}) + 1 мин`, iso: at(z.shkiya, +1), tefillin: false },
        { label: '19:30', iso: `${DAY}T19:30:00${OFF}`, tefillin: false },
        { label: '23:30', iso: `${DAY}T23:30:00${OFF}`, tefillin: false },
      ];
      for (const c of checks) {
        await test.step(`${c.label}: строка ${c.tefillin ? 'есть' : 'нет'}`, async () => {
          // источник: «מה רצוי» п.2 — только в часы, когда ещё можно надеть תפילין; не после שקיעה и не ночью
          const rows = await openHomeAt(page, c.iso);
          const tf = tefillinRows(rows);
          expect(tf, `строк «הנחת תפילין» в ${c.label}`).toHaveLength(c.tefillin ? 1 : 0);
          if (c.tefillin) expect(tf[0].sub).toBe(TEFILLIN_TEXT);
        });
      }
    } finally {
      await restoreTodayReminders(browser, testInfo);
    }
  });
});
